-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Uncorrected misstatements representation vs. auditor''s independent assessment
(1, 'Written Representations', 'During the audit of Apex Regional Bank for the year ended December 31, 2025, the engagement team at Langston & Pierce CPA identified $38,000 in aggregate uncorrected misstatements. The management representation letter states that management believes these uncorrected misstatements are immaterial. If the auditor independently concludes the misstatements are material, what is the most likely outcome?', '["The auditor accepts management''s assessment because the representation letter constitutes sufficient evidence of immateriality", "The auditor considers the impact on the audit opinion and may issue a qualified or adverse opinion regardless of management''s representation", "The auditor withdraws from the engagement immediately upon disagreement with management", "The auditor requires management to adjust all misstatements before issuing any opinion"]'::jsonb, 1, 'Under AU-C 580, written representations complement but do not replace the auditor''s responsibility to form an independent opinion. If uncorrected misstatements are material, AU-C 705 requires modification of the opinion regardless of management''s representation. Choice A is incorrect because management''s representation about immateriality does not override the auditor''s independent assessment of the misstatements'' effect on the financial statements.', 'medium', 3),

-- Q2: easy / L1 — Written form requirement for management representations
(1, 'Written Representations', 'Under AU-C 580, in what form must the auditor obtain management representations?', '["In a written representation letter signed by management", "Through oral statements documented in the audit workpapers", "In either written or oral form at the auditor''s discretion", "Through a combination of email confirmations and verbal assurances"]'::jsonb, 0, 'AU-C 580.09 requires management representations to be provided in a written representation letter. Written form is mandatory because it reduces the possibility of misunderstandings between the auditor and management. Choice B is incorrect because oral representations alone, even if documented in workpapers, do not satisfy the requirement for a formal written letter signed by management.', 'easy', 1),

-- Q3: hard / L4 — Evaluating qualified language in the representation letter
(1, 'Written Representations', 'The audit of Kensington Capital Partners for the year ended December 31, 2025 is nearing completion. The CFO provides the management representation letter but includes qualifying language stating, ''To the best of our knowledge, based on inquiries of department heads, all significant transactions have been recorded.'' The engagement partner at Morales & Webb CPA must evaluate the effect of this qualified language. What is the most appropriate course of action?', '["Accept the qualified language because management has explained its basis for the limitation", "Disregard the representation letter entirely and rely solely on substantive audit procedures", "Document the qualified language in the workpapers without further action or follow-up", "Discuss the qualified language with management, evaluate its effect on the reliability of all representations, and consider the impact on the audit opinion"]'::jsonb, 3, 'Under AU-C 580.20, when written representations contain qualifying language, the auditor must discuss the matter with management and evaluate whether the qualification affects representation reliability. If unresolved, AU-C 580.A30 requires assessment of the impact on the audit opinion, potentially including a scope limitation. Choice A is incorrect because qualifying language undermines the completeness assertion and cannot simply be accepted at face value.', 'hard', 4),

-- Q4: medium / L3 — Completeness of information representation omitted from letter
(1, 'Written Representations', 'Baxter & Lowe CPA is completing the audit of Crescent Dynamics Inc. for the year ended December 31, 2025. The management representation letter is comprehensive but omits the standard representation that all financial records and related data have been made available to the auditor. The engagement partner must assess the significance of this omission. What is the most likely effect?', '["The omission has no effect if all other audit procedures were completed satisfactorily", "The auditor should note the omission in the workpapers but may still issue an unmodified opinion", "The auditor should request management to include the completeness representation, and if refused, treat it as a scope limitation", "The auditor should perform additional substantive procedures to compensate for the missing representation"]'::jsonb, 2, 'AU-C 580.10 requires management to represent that it has provided the auditor with access to all relevant records and information. If management refuses to provide this required representation, AU-C 580.19 treats the refusal as a scope limitation, potentially resulting in a qualified opinion or disclaimer of opinion. Choice A is incorrect because the completeness representation is a foundational requirement whose absence creates doubt about unrestricted audit access.', 'medium', 3),

-- Q5: medium / L2 — Addressee of the management representation letter
(1, 'Written Representations', 'Prescott & Hale CPA is completing the audit of Evergreen Supply Corp. for the year ended December 31, 2025. The staff auditor preparing the management representation letter template asks the engagement partner to whom the letter should be addressed. Under AU-C 580, the management representation letter should be addressed to:', '["The chair of the entity''s audit committee", "The auditor, typically the engagement partner or the audit firm", "The board of directors of the entity being audited", "The Securities and Exchange Commission"]'::jsonb, 1, 'AU-C 580.11 requires the management representation letter to be addressed to the auditor. Because the representations support the auditor''s conclusions, the letter is directed to the engagement partner or audit firm performing the engagement. Choice A is incorrect because while the audit committee has governance oversight, written representations are a communication from management to the auditor, not to those charged with governance.', 'medium', 2),

-- Q6: medium / L2 — Auditor requesting additional representations beyond standard items
(1, 'Written Representations', 'During the audit of Silverstone Aerospace LLC for the year ended December 31, 2025, the engagement team at Crawford & Beck CPA identifies unusual intercompany transactions totaling $4.2 million. The engagement partner wants to include a specific representation about these transactions beyond the standard required items. Under AU-C 580, the auditor''s authority to request additional representations is:', '["Permitted, because the auditor may request written representations about any matter considered necessary to support other audit evidence", "Prohibited, because only the standard representations prescribed by AU-C 580 may be included in the letter", "Permitted only if approved by the entity''s audit committee in advance", "Permitted only for matters involving amounts exceeding overall materiality"]'::jsonb, 0, 'AU-C 580.A11 permits the auditor to request additional written representations about matters specific to the entity beyond the standard required items. The auditor tailors the representation letter to address significant or unusual transactions warranting explicit management acknowledgment. Choice B is incorrect because AU-C 580 provides a minimum list of required representations and expressly allows supplementation with engagement-specific items.', 'medium', 2),

-- Q7: easy / L1 — Primary purpose of the management representation letter
(1, 'Written Representations', 'What is the primary purpose of the management representation letter obtained during an audit?', '["To serve as the sole source of audit evidence for assertions that are difficult to test", "To transfer legal liability for the financial statements from the auditor to management", "To satisfy the audit committee''s documentation requirements for the engagement", "To confirm management''s responsibility for the financial statements and to support other audit evidence obtained"]'::jsonb, 3, 'Under AU-C 580.03, the management representation letter serves to confirm management''s responsibility for the fair presentation of financial statements and to provide written support for audit evidence obtained through other procedures. Choice A is incorrect because written representations complement rather than replace other forms of audit evidence and cannot serve as the sole basis for the auditor''s conclusions.', 'easy', 1),

-- Q8: medium / L2 — Representation about selection of accounting policies
(1, 'Written Representations', 'Fletcher & Garza CPA is auditing Brookfield Technologies Inc. for the year ended December 31, 2025. Brookfield adopted a new revenue recognition method during the year. The engagement partner includes a specific representation about accounting policies. Under AU-C 580, management should represent that:', '["All accounting policies were reviewed and approved by an independent accounting firm before adoption", "The entity''s external legal counsel approved all accounting policy changes made during the year", "The selection and application of accounting policies are appropriate for the entity''s financial reporting framework", "All accounting policies have remained unchanged from the prior year to ensure financial statement comparability"]'::jsonb, 2, 'AU-C 580.10 requires management to represent that the financial statements are prepared in accordance with the applicable financial reporting framework, which includes the appropriateness of selected accounting policies. Management acknowledges that its policy choices are suitable for the entity''s circumstances. Choice D is incorrect because changes in accounting policies are permissible under GAAP when the new policy is preferable, so consistency is not a required representation.', 'medium', 2),

-- Q9: hard / L4 — Evaluating contradictory evidence against written representations
(1, 'Written Representations', 'The audit of Ridgeway Consolidated Holdings for the year ended December 31, 2025 reveals that the management representation letter states no related-party transactions exist beyond those already disclosed. However, the engagement team at Dalton & Chase CPA discovered a $1.8 million receivable from the CEO''s privately held company that management did not disclose. What is the most appropriate response?', '["Accept the representation letter because the receivable was identified through other audit procedures", "Reevaluate the reliability of all management representations, perform additional procedures to determine the effect on the financial statements, and consider the implications for the auditor''s report", "Immediately withdraw from the engagement because management has committed fraud", "Disclose the related-party transaction directly in the auditor''s report without modifying the opinion"]'::jsonb, 1, 'Under AU-C 580.17, when the auditor identifies information contradicting management''s written representations, the auditor must investigate the inconsistency, reevaluate the reliability of other representations, and determine whether additional procedures are needed. The contradiction may indicate intentional misrepresentation requiring evaluation under AU-C 240. Choice C is incorrect because contradictory evidence does not automatically constitute fraud; the auditor must first investigate the circumstances.', 'hard', 4),

-- Q10: medium / L2 — Representation about going concern plans
(1, 'Written Representations', 'Halcyon Medical Devices Inc. has experienced recurring operating losses, and the engagement team at Pearce & Whitaker CPA is evaluating going concern for the year ended December 31, 2025. The management representation letter should include a going concern representation that addresses:', '["Management''s plans intended to mitigate the conditions raising substantial doubt about the entity''s ability to continue as a going concern", "A guarantee that the entity will continue operations for at least the next fiscal year", "The specific banks and lenders management intends to contact for additional financing", "A projection of cash flows for the next three fiscal years certified by a third-party appraiser"]'::jsonb, 0, 'Under AU-C 580.A12, when going concern issues exist, the representation letter should include management''s plans to address the conditions raising substantial doubt. Management represents the feasibility and intended execution of its plans, not a guarantee of the outcome. Choice B is incorrect because management cannot guarantee future operations; the representation concerns the reasonableness of plans, not the certainty of their success.', 'medium', 2),

-- Q11: medium / L2 — Representation letter when management changes near report date
(1, 'Written Representations', 'On January 15, 2026, Thornfield Industries replaced its CEO and CFO. The engagement team at Mercer & Quinn CPA is completing the audit for the year ended December 31, 2025, and the auditor''s report will be dated February 20, 2026. The new officers have been in their roles for only five weeks. Under AU-C 580, how should the representation letter be handled?', '["The former CEO and CFO must sign the letter because they managed the entity during the audit period", "The representation letter requirement is waived when management changes occur near the report date", "The auditor should obtain two separate representation letters from both former and current management", "The current CEO and CFO should sign the letter, and the auditor should consider whether additional procedures are needed regarding their knowledge of the period"]'::jsonb, 3, 'Under AU-C 580.12, the representation letter is signed by those with appropriate responsibilities at the date of the letter. When management has recently changed, the current officers sign and represent matters for the full period. The auditor should consider whether additional procedures are needed to address any knowledge gaps. Choice A is incorrect because the letter is dated as of the auditor''s report date, requiring the individuals currently in office as signatories.', 'medium', 2),

-- Q12: easy / L1 — Representation about management''s internal control responsibility
(1, 'Written Representations', 'Under AU-C 580, which of the following is a matter typically addressed in the management representation letter?', '["The auditor''s assessment of the effectiveness of the entity''s internal controls", "The audit committee''s evaluation of the engagement partner''s independence", "Management''s acknowledgment of its responsibility for designing and maintaining internal controls relevant to financial reporting", "The internal audit department''s opinion on the accuracy of the financial statements"]'::jsonb, 2, 'AU-C 580.10 requires management to acknowledge its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. This representation reinforces the distinction between management''s and the auditor''s roles. Choice A is incorrect because the auditor''s assessment of internal controls is the auditor''s own work product, not a matter for management to represent.', 'easy', 1),

-- Q13: easy / L1 — Representation about providing access to all records
(1, 'Written Representations', 'Under AU-C 580, management must represent that it has provided the auditor with:', '["A complete list of all shareholders and their ownership percentages", "Access to all information relevant to the preparation of the financial statements, including all records, documentation, and personnel", "Copies of all correspondence with regulatory agencies during the audit period", "A detailed schedule of every adjusting journal entry made during the fiscal year"]'::jsonb, 1, 'AU-C 580.10 requires management to represent that it has provided the auditor with access to all relevant information, records, and personnel as agreed upon in the engagement letter. This completeness assertion is fundamental to ensuring an unrestricted audit scope. Choice A is incorrect because the required representation broadly encompasses all information relevant to financial statement preparation and the audit, not just shareholder details.', 'easy', 1),

-- Q14: medium / L2 — Representation about reasonableness of estimate assumptions
(1, 'Written Representations', 'Durant Manufacturing Inc. reports a $3.6 million warranty liability involving significant estimation uncertainty on its December 31, 2025 balance sheet. The engagement team at Caldwell & Reeves CPA requests a specific representation about this estimate. Under AU-C 580, management should represent that:', '["The significant assumptions used in making the warranty liability estimate are reasonable in the circumstances", "The warranty liability estimate has been independently verified by a third-party actuary", "The warranty liability amount is guaranteed to be accurate within 5% of the actual outcome", "All warranty claims received after year-end have been included in the estimate regardless of when the obligation arose"]'::jsonb, 0, 'AU-C 580.10 requires management to represent that significant assumptions used in accounting estimates are reasonable. For complex estimates like warranty liabilities, this representation addresses the subjective inputs rather than guaranteeing outcomes. Choice B is incorrect because AU-C 580 does not require third-party verification of estimates; the representation concerns the reasonableness of assumptions management used, not external validation.', 'medium', 2),

-- Q15: easy / L2 — Representation about title to assets
(1, 'Written Representations', 'Summit Ridge Properties LLC reports $12 million in investment real estate on its December 31, 2025 balance sheet. The engagement team at Novak & Sterling CPA requests a representation about these assets. Under AU-C 580, management should represent that:', '["All investment properties have been appraised by a licensed appraiser within the past 12 months", "All properties are fully insured against fire, flood, and natural disaster losses", "All leases on the investment properties will be renewed by existing tenants at current terms", "The entity has satisfactory title to all owned assets, and any liens or encumbrances are properly disclosed in the financial statements"]'::jsonb, 3, 'AU-C 580.10 requires management to represent that the entity holds satisfactory title to assets and that any liens, pledges, or encumbrances are properly disclosed. This assertion supports the rights and obligations tested during the audit. Choice A is incorrect because the representation addresses legal ownership and disclosed encumbrances, not the frequency or method of property appraisals, which relates to valuation.', 'easy', 2),

-- Q16: medium / L3 — Written representations do not substitute for substantive procedures
(1, 'Written Representations', 'During the audit of Cascadia Logistics Group for the year ended December 31, 2025, a staff auditor at Pemberton & Hale CPA proposes skipping confirmation of a $2.1 million accounts receivable balance because the management representation letter states all receivables are valid and collectible. How does this proposal most likely affect the sufficiency of audit evidence?', '["The approach is acceptable because the representation letter constitutes external evidence obtained directly from management", "The approach is acceptable if the receivable balance is below the engagement''s performance materiality threshold", "The approach is inappropriate because written representations do not provide sufficient appropriate audit evidence to replace substantive procedures for significant balances", "The approach is inappropriate only if the client has a history of material accounts receivable write-offs"]'::jsonb, 2, 'Under AU-C 580.04, written representations are necessary audit evidence but do not provide sufficient appropriate evidence on their own for significant matters. The auditor must corroborate representations with procedures such as confirmations or subsequent cash receipts testing. Choice A is incorrect because management representations are internal evidence originating from the entity being audited and rank among the least reliable forms in the evidence hierarchy.', 'medium', 3),

-- Q17: hard / L3 — Contradictory representations and broader risk assessment impact
(1, 'Written Representations', 'During the audit of Pacific Ventures Holdings for the year ended December 31, 2025, the engagement team at Sinclair & Caldwell CPA obtains a management representation letter in which the CFO represents that all related-party transactions have been disclosed. However, independent confirmation procedures reveal three undisclosed related-party loans totaling $890,000. How does this contradiction most likely affect the overall audit?', '["The impact is limited to the related-party transactions balance and requires no broader reassessment", "The auditor should reassess the integrity of management and the reliability of all written representations, which may lead to expanded procedures and reconsideration of the overall audit strategy", "The auditor should issue an adverse opinion solely based on the related-party omission", "The auditor should accept the representation letter and adjust only the related-party footnote disclosure"]'::jsonb, 1, 'Under AU-C 580.17–.18, contradictory evidence regarding written representations requires the auditor to reconsider the reliability of management as a whole, not just the specific assertion. Per AU-C 240.A11, an intentional omission may indicate a fraud risk factor affecting the overall audit strategy. Choice A is incorrect because a material contradiction in representations casts doubt on management''s integrity across all areas, not just the isolated assertion contradicted.', 'hard', 3),

-- Q18: medium / L3 — Noncompliance with laws and regulations representation
(1, 'Written Representations', 'Hargrove Pharmaceuticals Inc. operates in a heavily regulated industry. During the audit for the year ended December 31, 2025, the engagement team at Whitmore & Dean CPA identifies potential noncompliance with FDA labeling requirements. The management representation letter includes a general statement about compliance with laws and regulations. How does the potential noncompliance most likely affect the auditor''s evaluation of the written representations?', '["The auditor should request a specific representation about the FDA labeling matter and evaluate whether the general compliance representation is consistent with the evidence obtained", "The general compliance representation is sufficient regardless of the potential noncompliance identified during testing", "The auditor should remove the compliance representation from the letter to avoid a management misrepresentation", "The potential noncompliance has no effect on the representation letter because regulatory matters fall outside the financial statement audit scope"]'::jsonb, 0, 'Under AU-C 580.A11, the auditor may request representations about specific matters, including known or potential noncompliance with laws and regulations. When evidence of noncompliance exists, the auditor should evaluate consistency between the general representation and audit findings under AU-C 250. Choice B is incorrect because a general compliance representation does not adequately address known potential noncompliance requiring specific management acknowledgment.', 'medium', 3),

-- Q19: hard / L4 — Representation letter in group audit context (AU-C 600)
(1, 'Written Representations', 'Westbrook Global Industries has subsidiaries in four countries, and the group engagement team at Archer & Blackwell CPA is conducting the group audit for the year ended December 31, 2025. Component auditors in Germany and Japan have completed their work. The group engagement partner must determine the approach for obtaining written representations. Under AU-C 600, what is the most appropriate approach?', '["Only the parent company''s CEO and CFO provide a representation letter covering all components", "Component auditors provide representations on behalf of component management, eliminating the need for separate component letters", "Representations are required only from components where misstatements were identified during the audit", "The group engagement team obtains representations from group management, and may also request representations from component management as appropriate for the engagement"]'::jsonb, 3, 'Under AU-C 600.40, the group engagement team obtains written representations from group management about the group financial statements. The group engagement partner may also determine it is necessary to request representations from component management, depending on the nature and extent of component auditor involvement. Choice A is incorrect because while parent management provides group-level representations, additional component-level representations may be needed for significant components.', 'hard', 4),

-- Q20: hard / L4 — Evaluating representation reliability when management competency is questioned
(1, 'Written Representations', 'During the audit of Lynwood Fabricators Inc. for the year ended December 31, 2025, the engagement team at Harper & Sullivan CPA discovers that the controller, who is a signatory of the management representation letter, has limited understanding of the complex accounting standards applied to the company''s $6.4 million in derivative instruments. The engagement partner must evaluate how to proceed. What is the most appropriate course of action?', '["Accept the representation letter as written because the requirement is only that management signs the letter", "Withdraw from the engagement because management cannot provide competent representations", "Obtain the representation letter from management but increase the extent of substantive testing on derivatives and consider involving a specialist to evaluate the disclosures", "Require the controller to complete professional training on derivatives before signing the letter"]'::jsonb, 2, 'Under AU-C 580.A23, the auditor considers whether representatives can competently provide reliable representations on the matters in question. When doubts exist about management''s competency on specific technical matters, the auditor should augment evidence through expanded procedures or specialist involvement per AU-C 620. Choice A is incorrect because AU-C 580 requires the auditor to evaluate whether the representatives can reasonably provide reliable representations, not merely obtain a signature.', 'hard', 4),

-- Q21: medium / L2 — Representation about absence of side agreements
(1, 'Written Representations', 'The engagement team at Beckett & Lowe CPA is completing the audit of Crestview Logistics Corp. for the year ended December 31, 2025. Crestview has a $7.8 million revenue contract with a government agency. The engagement partner requests a specific representation about side agreements. Under AU-C 580, management should represent that:', '["All government contracts have been reviewed and approved by the entity''s legal department", "There are no side agreements or oral modifications to contractual arrangements that have not been disclosed to the auditor", "All contract revenue has been collected within 90 days of the billing date", "Government contract pricing has been benchmarked against prevailing industry standards"]'::jsonb, 1, 'AU-C 580.A11 supports requesting representations about matters important to the audit. Side agreements or undisclosed modifications to contracts can materially affect revenue recognition, and management should confirm no such arrangements exist outside the disclosed terms. Choice A is incorrect because legal department review is an internal control procedure, not a representation about the completeness of disclosed contractual terms relevant to the financial statements.', 'medium', 2),

-- Q22: medium / L3 — Fair value representation contradicted by audit evidence
(1, 'Written Representations', 'Pinnacle Capital Advisors holds a portfolio of Level 3 investments valued at $7.5 million on its December 31, 2025 balance sheet. The management representation letter states that fair value assumptions are reasonable. During testing, the engagement team at Conway & Price CPA finds that management''s valuation model uses a discount rate 200 basis points below comparable market rates. How does this finding most likely affect the auditor''s evaluation of the written representations?', '["The auditor should evaluate whether the fair value assumption representation is contradicted by the evidence and determine whether the discount rate difference results in a material misstatement", "The auditor should accept the representation because management has discretion to select any discount rate it considers appropriate", "The auditor should require management to engage a third-party valuation specialist before signing the representation letter", "The auditor should remove the fair value representation from the letter because Level 3 measurements are inherently subjective"]'::jsonb, 0, 'Under AU-C 580.17, the auditor must evaluate whether written representations are consistent with other audit evidence. A significant discrepancy between management''s discount rate and market-comparable rates raises questions about the reasonableness of assumptions, requiring assessment of potential misstatement under AU-C 540. Choice B is incorrect because while management exercises judgment in selecting assumptions, the auditor must independently evaluate reasonableness when evidence suggests a material deviation from market data.', 'medium', 3),

-- Q23: easy / L1 — Subsequent events representation in the management letter
(1, 'Written Representations', 'Under AU-C 580, what must management represent regarding events occurring after the balance sheet date?', '["That no events of any kind occurred after the balance sheet date", "That all subsequent events have been audited by the engagement team before the report date", "That any subsequent events have been approved by the audit committee before financial statement disclosure", "That all events occurring after the date of the financial statements that require adjustment or disclosure have been properly addressed"]'::jsonb, 3, 'AU-C 580.10 requires management to represent that all subsequent events requiring adjustment or disclosure under the applicable financial reporting framework have been appropriately reflected in the financial statements. This representation supports the auditor''s subsequent events procedures under AU-C 560. Choice A is incorrect because subsequent events routinely occur; the representation addresses whether those events have been properly adjusted or disclosed, not whether they happened.', 'easy', 1),

-- Q24: hard / L4 — Written representations in review vs. audit engagements
(1, 'Written Representations', 'Davis & Rowland CPA performs a review engagement of Parkside Ventures LLC for the year ended December 31, 2025, under AR-C 90. The firm also audits Ridgewood Industries under AU-C standards. A staff accountant asks whether written representation requirements differ between these two engagements. Which statement best describes the difference?', '["Written representations are required for audits under AU-C 580 but are entirely optional for review engagements under AR-C 90", "Both engagements require identical representation letters with the same content and signatories", "Both engagements require written representations from management, but the review engagement representations under AR-C 90 are more limited in scope, focusing on management''s responsibility and completeness of information", "Review engagements require written representations only when the accountant identifies material departures from the financial reporting framework"]'::jsonb, 2, 'Both AU-C 580 (audits) and AR-C 90.34–.35 (reviews) require written management representations, but the scope differs. Audit representations cover broader assertions including fraud, noncompliance, and specific account matters, while review representations focus on management''s responsibility and completeness of information provided. Choice A is incorrect because AR-C 90 explicitly requires written representations in every review engagement; they are not optional.', 'hard', 4),

-- Q25: easy / L1 — Periods covered by the representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter covers representations about:', '["Only the three-month period immediately before the auditor''s report date", "All periods referred to in the auditor''s report, including any comparative periods presented", "The twelve months following the balance sheet date for prospective matters", "Only the current fiscal year, regardless of whether comparative statements are presented"]'::jsonb, 1, 'AU-C 580.14 requires the written representations to cover all periods referred to in the auditor''s report. When comparative financial statements are presented, management''s representations extend to all periods covered. Choice D is incorrect because if the auditor''s report covers comparative periods, management must provide representations addressing both years, not just the current year.', 'easy', 1),

-- Q26: medium / L3 — Contingency representation contradicted by attorney response
(1, 'Written Representations', 'During the audit of Atlas Construction Group for the year ended December 31, 2025, the engagement team at Morgan & Ellis CPA learns that Atlas is a defendant in a $4.8 million construction defect lawsuit filed in October 2025. The management representation letter states that all known litigation has been disclosed. However, the attorney''s response letter indicates a probable loss outcome that management has not accrued. How does this inconsistency most likely affect the auditor''s evaluation?', '["The auditor should evaluate whether the litigation representation is contradicted by the attorney''s assessment and determine whether the unrecorded probable loss is material to the financial statements", "The auditor should accept management''s representation because management has ultimate responsibility for financial statement assertions", "The auditor should rely on the attorney''s response and override management''s judgment about the loss accrual", "The auditor should request a revised attorney''s response that aligns with management''s assessment of the litigation"]'::jsonb, 0, 'Under AU-C 580.17, the auditor evaluates contradictions between written representations and other audit evidence, including attorney response letters under AU-C 501. A probable loss that is material and estimable requires accrual under ASC 450-20, and the inconsistency must be resolved. Choice B is incorrect because while management makes accounting decisions, the auditor cannot ignore contradictory evidence from the entity''s own legal counsel regarding loss contingencies.', 'medium', 3),

-- Q27: easy / L1 — Definition of ''management'' for representation letter purposes
(1, 'Written Representations', 'Under AU-C 580, who is considered management for purposes of signing the written representation letter?', '["Any employee who participated in preparing the financial statements during the audit period", "Members of management with appropriate responsibilities for the financial statements and knowledge of the matters concerned, typically the CEO and CFO", "The external legal counsel retained by the entity for the audit period", "The chair of the board of directors or the lead independent director"]'::jsonb, 1, 'AU-C 580.09 defines the signatories as members of management with appropriate responsibilities for the financial statements and knowledge of the matters concerned. In practice, the CEO and CFO or their equivalents typically sign. Choice A is incorrect because not every employee involved in financial statement preparation has the authority or responsibility to make representations on behalf of management.', 'easy', 1),

-- Q28: medium / L3 — Specific representations for particular accounts do not replace testing
(1, 'Written Representations', 'Garrison Electronics Inc. reports $5.3 million in capitalized development costs on its December 31, 2025 balance sheet. The engagement team at Palmer & Voss CPA has concerns about whether certain projects meet the capitalization criteria under ASC 730. The engagement partner includes a specific representation about development cost capitalization. How does this representation most likely affect the audit approach?', '["The specific representation eliminates the need for substantive testing of capitalized development costs", "The specific representation shifts the burden of proof to management if a misstatement is later discovered", "The specific representation supplements but does not replace the auditor''s substantive procedures, and any inconsistency with audit evidence should prompt further investigation", "The specific representation is unnecessary because capitalization criteria are objective standards that do not require management judgment"]'::jsonb, 2, 'Under AU-C 580.04, written representations are necessary information the auditor requires, but they complement rather than replace other audit evidence. A specific representation about capitalization adds to the evidence base, but the auditor must still test whether projects meet ASC 730 criteria. Choice A is incorrect because no written representation, regardless of specificity, substitutes for substantive procedures on material balances requiring significant judgment.', 'medium', 3),

-- Q29: medium / L2 — Representation about compliance with debt covenants
(1, 'Written Representations', 'Millbrook Financial Services Inc. has debt covenants requiring maintenance of a current ratio above 1.5 and debt-to-equity below 2.0. During the audit for the year ended December 31, 2025, the engagement team at Riley & Shaw CPA includes a representation about contractual compliance. Under AU-C 580, management should represent that:', '["The entity''s financial ratios will remain in compliance with debt covenants for the next three fiscal years", "All aspects of contractual agreements that could affect the financial statements, including any noncompliance provisions, have been disclosed to the auditor", "The entity''s lenders have waived all debt covenant requirements for the current audit period", "The entity has negotiated favorable terms on all outstanding debt instruments during the year"]'::jsonb, 1, 'AU-C 580.A11 supports requesting representations about noncompliance with contractual agreements that could materially affect the financial statements. Management confirms all relevant covenant terms and any noncompliance have been communicated to the auditor. Choice A is incorrect because forward-looking guarantees about future covenant compliance are beyond the scope of the representation letter, which addresses matters through the date of the auditor''s report.', 'medium', 2),

-- Q30: easy / L1 — Entity from which representations are obtained
(1, 'Written Representations', 'Under AU-C 580, the auditor obtains written representations from management of:', '["The entity whose financial statements are being audited", "The audit firm performing the engagement", "The regulatory body overseeing the entity''s industry", "The entity''s primary lending institution"]'::jsonb, 0, 'AU-C 580.09 requires written representations from management of the entity being audited. The representations confirm management''s acknowledgments and assertions about the financial statements under audit. Choice B is incorrect because the audit firm is the recipient of the representation letter, not the provider—representations flow from the entity''s management to the auditor to support audit conclusions.', 'easy', 1)
;

COMMIT;
